class Solution {
    public int heightChecker(int[] heights){
        int[] expected=heights.clone();
        Arrays.sort(expected);
        int mismatches=0;
        for(int i=0;i<heights.length;i++)if(heights[i]!=expected[i])mismatches++;
        return mismatches;
    }
}

code.kotlin:
class Solution {
    fun heightChecker(heights:IntArray):Int{
        val expected=heights.sortedArray();
        return heights.indices.count{
            heights[it]!=expected[it]
        }
    }
}

code.cpp:
class Solution {
    public: int heightChecker(vector<int>& heights){
        vector<int> expected=heights;
        sort(expected.begin(),expected.end());
        int mismatches=0;
        for(int i=0;i<(int)heights.size();++i)mismatches+=heights[i]!=expected[i];
        return mismatches;
    }
};
